def normalize_items(items):
    result = {}
    for item in items:
        sku = item["sku"].strip().lower()
        qty = item["qty"]
        if not sku or not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("Invalid item")
        result[sku] = result.get(sku, 0) + qty
    return result

